import {ControlGroup} from '@github-ui/control-group'
import {AppsIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import pluralize from 'pluralize'
import {useState} from 'react'

import type {OwnerSelection} from '../types/repo-creation-types'
import {MarketplaceAppsSelectionDialog} from './MarketplaceAppsSelectionDialog'

export function MarketplaceAppsSelectionV2({
  ownerSelection,
  manuallySelectedListingIds,
  onListingsSave,
}: {
  ownerSelection: OwnerSelection
  manuallySelectedListingIds: number[]
  onListingsSave: (listings: number[]) => void
}) {
  const [showDialog, setShowDialog] = useState(false)

  const {installableApps, name} = ownerSelection

  return (
    <>
      <ControlGroup>
        <ControlGroup.Item>
          <ControlGroup.Title className="fgColor-default">Connect GitHub Apps</ControlGroup.Title>
          <ControlGroup.Description>Connect this repository to apps {name} is subscribed to</ControlGroup.Description>
          <ControlGroup.Custom>
            <ChooseAppsButton
              onClick={() => setShowDialog(true)}
              selectedListingsCount={
                manuallySelectedListingIds.length + installableApps.filter(x => x.autoInstall).length
              }
            />
          </ControlGroup.Custom>
        </ControlGroup.Item>
      </ControlGroup>
      {showDialog && (
        <MarketplaceAppsSelectionDialog
          marketplaceListings={installableApps}
          orgName={name}
          onClose={() => setShowDialog(false)}
          manuallySelectedListingIds={manuallySelectedListingIds}
          onSave={onListingsSave}
        />
      )}
    </>
  )
}

function ChooseAppsButton({selectedListingsCount, onClick}: {selectedListingsCount: number; onClick: () => void}) {
  if (selectedListingsCount > 0) {
    return (
      <Button leadingVisual={<AppsIcon />} onClick={onClick}>
        {`${selectedListingsCount} ${pluralize('app', selectedListingsCount)} selected`}
      </Button>
    )
  }

  return <Button onClick={onClick}>Choose apps</Button>
}

try{ MarketplaceAppsSelectionV2.displayName ||= 'MarketplaceAppsSelectionV2' } catch {}
try{ ChooseAppsButton.displayName ||= 'ChooseAppsButton' } catch {}