import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {UnsafeHTMLBox} from '@github-ui/safe-html/UnsafeHTML'
import {SingleSignOnBanner} from '@github-ui/single-sign-on-banner'
import {Flash, Heading, Stack} from '@primer/react'
import {Banner} from '@primer/react/experimental'
import {useEffect, useRef} from 'react'

export function RepoCreationForm({
  children,
  flash,
  title,
  description,
  protectedOrgLogins,
  submitButton,
  onSubmit,
  useHeaderV2 = false,
  isStaffUser = false,
  staffFeedbackUrl,
}: {
  children: React.ReactNode
  flash: string
  title: string
  description: string | React.ReactNode
  protectedOrgLogins: string[]
  submitButton?: React.ReactNode
  onSubmit?: () => void
  useHeaderV2?: boolean
  isStaffUser?: boolean
  staffFeedbackUrl?: string
}) {
  const flashRef = useRef<HTMLDivElement | null>(null)

  useEffect(() => {
    flashRef.current?.focus()
  }, [flash, flashRef])

  return (
    <form
      // By default HTML5 form will focus on the first required input with missing value on submit.
      // Although, this is fine for simple input fields it doesn't work nicely with custom inputs such as owner selector.
      // In result, it breaks our custom focus order.
      // This property disables default form behavior.
      noValidate
      onSubmit={e => {
        e.preventDefault()
        onSubmit?.()
      }}
      className={`container-md px-3 px-md-4 px-lg-5 my-${useHeaderV2 ? 4 : 6}`}
    >
      {!useHeaderV2 && flash && (
        <Flash
          tabIndex={0}
          ref={flashRef}
          data-testid="repo-creation-form-error-flash"
          variant="danger"
          className="mb-2"
        >
          <UnsafeHTMLBox html={flash} />
        </Flash>
      )}
      <div>
        {useHeaderV2 ? (
          <Stack direction="horizontal" align="center">
            <Stack.Item>
              <Heading as="h1" variant="medium">
                {title}
              </Heading>
            </Stack.Item>
            <Stack.Item>
              {isStaffUser ? (
                <BetaLabel feedbackUrl={staffFeedbackUrl}>Staff</BetaLabel>
              ) : (
                <BetaLabel>Preview</BetaLabel>
              )}
            </Stack.Item>
          </Stack>
        ) : (
          <Heading as="h1" className="f2">
            {title}
          </Heading>
        )}
        <span className="fgColor-muted">{description}</span>
      </div>
      {!useHeaderV2 && <hr className="my-2" />}
      <div className={`text-italic${useHeaderV2 ? ' fgColor-muted' : ''}`}>
        Required fields are marked with an asterisk (*).
      </div>
      <div className={`mt-${useHeaderV2 ? 4 : 2}`}>
        <SingleSignOnBanner protectedOrgs={protectedOrgLogins} />
      </div>
      {useHeaderV2 && flash && (
        <Banner
          ref={flashRef}
          data-testid="repo-creation-form-error-banner"
          variant="critical"
          title="Error"
          hideTitle
          className="mt-2"
        >
          <Banner.Description>
            <UnsafeHTMLBox html={flash} />
          </Banner.Description>
        </Banner>
      )}
      {children}
      <Stack direction="horizontal" justify="end">
        {submitButton}
      </Stack>
    </form>
  )
}

try{ RepoCreationForm.displayName ||= 'RepoCreationForm' } catch {}