import {GitHubAvatar} from '@github-ui/github-avatar'
import {SearchIcon} from '@primer/octicons-react'
import {ActionList, Dialog, TextInput} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {useState} from 'react'

import type {MarketplaceAppListing} from '../types/repo-creation-types'

export function MarketplaceAppsSelectionDialog({
  marketplaceListings,
  orgName,
  onClose,
  manuallySelectedListingIds,
  onSave,
}: {
  marketplaceListings: MarketplaceAppListing[]
  orgName: string
  onClose: () => void
  manuallySelectedListingIds: number[]
  onSave: (listingIds: number[]) => void
}) {
  const [selectedListingIds, setSelectedListingIds] = useState(manuallySelectedListingIds)
  const [filterValue, setFilterValue] = useState('')

  const onSelect = (listingId: number) => {
    if (selectedListingIds.includes(listingId)) {
      setSelectedListingIds(selectedListingIds.filter(x => x !== listingId))
    } else {
      setSelectedListingIds([...selectedListingIds, listingId])
    }
  }

  const filteredListings = filterValue
    ? marketplaceListings.filter(listing => listing.name.toLowerCase().includes(filterValue.toLowerCase()))
    : marketplaceListings

  return (
    <Dialog
      onClose={onClose}
      title="Choose GitHub Apps"
      width="large"
      height={filteredListings.length >= 10 ? 'large' : 'auto'}
      footerButtons={[
        {
          buttonType: 'default',
          content: 'Cancel',
          onClick: onClose,
        },
        {
          buttonType: 'primary',
          content: 'Save',
          onClick: () => {
            onSave(selectedListingIds)
            onClose()
          },
        },
      ]}
    >
      <TextInput
        leadingVisual={<SearchIcon />}
        placeholder="Search apps"
        aria-label="Search apps"
        value={filterValue}
        onChange={event => setFilterValue(event.target.value)}
        block
        className="mb-3"
      />
      {filteredListings.length > 0 ? (
        <MarketplaceListings
          displayedListings={filteredListings}
          onSelect={onSelect}
          orgName={orgName}
          selectedListingIds={selectedListingIds}
        />
      ) : (
        <Blankslate>
          <Blankslate.Heading>No apps found for `{filterValue}`</Blankslate.Heading>
          <Blankslate.Description>Adjust your search term to find other apps</Blankslate.Description>
        </Blankslate>
      )}
    </Dialog>
  )
}

function MarketplaceListings({
  displayedListings,
  onSelect,
  orgName,
  selectedListingIds,
}: {
  displayedListings: MarketplaceAppListing[]
  onSelect: (listingName: number) => void
  orgName: string
  selectedListingIds: number[]
}) {
  return (
    <ActionList selectionVariant="multiple" variant="full" role="listbox">
      {displayedListings.map(listing => (
        <ActionList.Item
          key={listing.id}
          onSelect={() => onSelect(listing.id)}
          inactiveText={getInactiveText(listing.autoInstall, orgName)}
          selected={listing.autoInstall || selectedListingIds.includes(listing.id)}
          role="option"
        >
          <ActionList.LeadingVisual>
            <GitHubAvatar
              square
              src={listing.primaryAvatarUrl}
              style={{backgroundColor: `#${listing.bgcolor}`, padding: 'var(--base-size-2)'}}
            />
          </ActionList.LeadingVisual>
          {listing.name}
          <ActionList.Description variant="block">{listing.normalizedShortDescription}</ActionList.Description>
        </ActionList.Item>
      ))}
    </ActionList>
  )
}

const getInactiveText = (autoInstall: boolean, orgName: string) =>
  autoInstall ? `Auto-installed by ${orgName}` : undefined

try{ MarketplaceAppsSelectionDialog.displayName ||= 'MarketplaceAppsSelectionDialog' } catch {}
try{ MarketplaceListings.displayName ||= 'MarketplaceListings' } catch {}