import {type CustomPropertyValuesTableRef, CustomPropertyValuesTableV2} from '@github-ui/custom-properties-editing'
import {
  propertyFieldsToChangedPropertiesMap,
  useEditCustomProperties,
} from '@github-ui/custom-properties-editing/use-edit-custom-properties'
import type {OwnerItem} from '@github-ui/owner-dropdown'
import {repositoriesPath} from '@github-ui/paths'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import type {Visibility} from '@github-ui/repos-list/repos-list-types'
import type {ReposSelectPanelWrapperItem} from '@github-ui/repos-select-panel-wrapper'
import {testIdProps} from '@github-ui/test-id-props'
import {useNavigate, useSearchParams} from '@github-ui/use-navigate'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {Button, Link, Stack, Timeline} from '@primer/react'
import {Banner} from '@primer/react/experimental'
import React, {useEffect, useMemo, useRef, useState} from 'react'
import {useLocation} from 'react-router-dom'

import {DescriptionV2} from '../components/DescriptionV2'
import {ImportPrompt} from '../components/ImportPrompt'
import {InitializeRepositoryOptionsV2} from '../components/InitializeRepositoryOptionsV2'
import {MarketplaceAppsSelectionV2} from '../components/MarketplaceAppsSelectionV2'
import {OwnerRepoSelection, type OwnerRepoSelectionRef} from '../components/OwnerRepoSelection'
import {RepoCreationForm} from '../components/RepoCreationForm'
import {RepoNameGeneratorV2} from '../components/RepoNameGeneratorV2'
import {RepoTemplateMenuV2} from '../components/RepoTemplateMenuV2'
import {VisibilitySelectionV2} from '../components/VisibilitySelectionV2'
import {getVisibilityOptions} from '../helpers/visibility'
import {useSelectedOwner} from '../hooks/use-selected-owner'
import {useUpdateTimeSpentOnPage} from '../hooks/use-update-time-spent-on-page'
import type {CreateFormV2Payload, License, RepoCreateBody} from '../types/repo-creation-types'
import styles from './CreateFormV2.module.css'

type RepoCreateBodyWithV2Metrics = RepoCreateBody & {
  metrics: {
    ['user_filtered_dropdown']: boolean
    ['user_set_template']: boolean
    ['user_changed_default_owner']: boolean
    ['user_changed_owner_after_setting_template']: boolean
    ['created_from_organization']: boolean
    ['prepopulated_template']: boolean
    ['owner_has_marketplace_apps']: boolean
    ['user_interacted_with_marketplace_apps']: boolean
    ['user_is_admin']: boolean
    ['elapsed_ms']: number
    ['submit_clicked_count']: number
    ['submit_errors']: string[]
    ['clicked_suggested_repo_name']: boolean
    ['used_suggested_repo_name']: boolean
    ['submitted_using_v2']: boolean
  }
}

export function CreateFormV2() {
  const [searchParams] = useSearchParams()
  const {
    initialOwnerSelection,
    privateModeEnabled,
    isGitHubEnterprise,
    ownerItems,
    suggestedRepoName,
    hasTemplateRepos,
    prepopulatedTemplate,
    repositoryImportLinkDataAttributes,
    protectedOrgLogins,
    docsUrls,
    licenses,
    tradeControlsPrivateRepoCreationWarning,
    tradeControlsUserPrivateRepoCreationWarning,
    isStaffUser,
    staffFeedbackUrl,
  } = useRoutePayload<CreateFormV2Payload>()

  const INITIAL_README = false
  // this must default to the 'No gitignore' option, as it's added to the list of templates inside the child
  // component
  const INITIAL_GITIGNORE = {id: '', text: 'No .gitignore'}
  // server passes "No license" as the first option, so select that. If the array is somehow empty,
  // then default to the same object so the form doesn't completely fall apart.
  const INITIAL_LICENSE = licenses[0] || {id: '', text: 'No license'}

  const {ownerSelection, changeOwner, errorMessage, fetchingOwnerDetails} = useSelectedOwner(initialOwnerSelection)
  const {propertyValuesMap, setPropertyValue, revertPropertyValue} = useEditCustomProperties(
    [{}],
    ownerSelection?.requiredDefinitions || [],
    [ownerSelection?.name],
  )
  const [createError, setCreateError] = useState('')
  const [submitErrors, setSubmitErrors] = useState<string[]>([])

  const [repositoryName, setRepositoryName] = useState(searchParams.get('name') || '')
  const [repoNameChanged, setRepoNameChanged] = useState(false)
  const [clickedSuggestedRepoName, setClickedSuggestedRepoName] = useState<boolean>(false)
  const [description, setDescription] = useState(searchParams.get('description') || '')
  const [descriptionIsValid, setDescriptionIsValid] = useState(true)
  const [selectedTemplateRepo, setSelectedTemplateRepo] = useState(prepopulatedTemplate || undefined)
  const isTemplatePrepopulated = !!prepopulatedTemplate
  const [includeAllBranches, setIncludeAllBranches] = useState(false)
  const [addReadme, setAddReadme] = useState(false)

  const [propertiesValidationClicked, setPropertiesValidationClicked] = useState(false)
  const [propertiesValidationPassed, setPropertiesValidationPassed] = useState(false)
  const [showReadOnlyPropertiesSummary, setShowReadOnlyPropertiesSummary] = useState(false)

  const [isCreating, setIsCreating] = useState(false)
  const [submitClicked, setSubmitClicked] = useState(false)

  // Initialize to false because repo name is initially blank
  const [isValidRepoName, setIsValidRepoName] = useState(false)
  const [repoNameValidityReason, setRepoNameValidityReason] = useState<string | undefined>(undefined)

  const [selectedGitignoreTemplate, setSelectedGitignoreTemplate] =
    useState<ReposSelectPanelWrapperItem>(INITIAL_GITIGNORE)

  const [selectedLicense, setSelectedLicense] = useState<License>(INITIAL_LICENSE)

  // The default visibility is 'private' if no owner is selected, per:
  // app/components/repositories/new/owner_empty_selection_option.rb#L1
  const [userSelectedVisibility, setUserSelectedVisibility] = useState<Visibility>()

  const [manuallyInstalledSelectedMarketplaceApps, setManuallyInstalledSelectedMarketplaceApps] = useState<number[]>([])

  const navigate = useNavigate()

  const {pathname} = useLocation()

  const ownerRepoSelectionRef = useRef<OwnerRepoSelectionRef | undefined>(undefined)
  const descriptionRef = useRef<HTMLTextAreaElement>(null)
  const propertiesTableRef = useRef<CustomPropertyValuesTableRef | undefined>(undefined)

  const displayedVisibilities = getVisibilityOptions(ownerSelection)
  const selectableVisibilities: Visibility[] = displayedVisibilities.filter(x => !x.message).map(x => x.visibility)

  const [userFilteredDropdown, setUserFilteredDropdown] = useState(false)
  const [userSetTemplate, setUserSetTemplate] = useState(false)
  const [userChangedDefaultOwner, setUserChangedDefaultOwner] = useState(false)
  const [userChangedOwnerAfterSettingTemplate, setUserChangedOwnerAfterSettingTemplate] = useState(false)
  const [userInteractedWithMarketplaceApps, setUserInteractedWithMarketplaceApps] = useState(false)

  const timeOnPage = useRef(0)
  const submitClickedCount = useRef(0)

  // TODO: the original create form also selects visibilities based on profile_readme
  // We might not need to support it in the future though, https://github.com/github/repos/issues/14307
  const selectedVisibility =
    selectableVisibilities.find(visibility => visibility === userSelectedVisibility) ||
    selectableVisibilities.find(visibility => visibility === searchParams.get('visibility')) ||
    selectableVisibilities.find(visibility => visibility === ownerSelection?.defaultVisibility) ||
    selectableVisibilities[0] ||
    'private'

  const invalidPropertyValues = new Set(
    Object.values(propertyValuesMap)
      .filter(p => !!p.error)
      .map(x => x.propertyName),
  )
  const hasInvalidPropertyValues = invalidPropertyValues.size > 0

  const templateDropdown = (
    <RepoTemplateMenuV2
      selectedTemplateRepo={selectedTemplateRepo}
      onRepoTemplateSelect={template => {
        // Reset all initialization options when a template is selected
        setAddReadme(INITIAL_README)
        setSelectedGitignoreTemplate(INITIAL_GITIGNORE)
        setSelectedLicense(INITIAL_LICENSE)
        setSelectedTemplateRepo(template)
        setUserSetTemplate(true)
      }}
      includeAllBranches={includeAllBranches}
      onIncludeAllBranchesChange={setIncludeAllBranches}
    />
  )

  useEffect(() => {
    if (ownerSelection && userSelectedVisibility && userSelectedVisibility !== selectedVisibility) {
      setUserSelectedVisibility(selectedVisibility)
    }
  }, [ownerSelection, userSelectedVisibility, selectedVisibility, setUserSelectedVisibility])

  const editableDefinitions = useMemo(() => {
    if (!ownerSelection) return []

    return ownerSelection.requiredDefinitions.filter(definition =>
      ownerSelection.editableDefinitionNames.includes(definition.propertyName),
    )
  }, [ownerSelection])

  const onOwnerChange = (owner: OwnerItem) => {
    // Don't track a user changing away from "Choose an owner"
    if (initialOwnerSelection) {
      setUserChangedDefaultOwner(true)
    }
    if (userSetTemplate) {
      setUserChangedOwnerAfterSettingTemplate(true)
    }
    changeOwner(owner)
    setManuallyInstalledSelectedMarketplaceApps([])
    setShowReadOnlyPropertiesSummary(false)
  }

  const updateTimeSpentOnPage = useUpdateTimeSpentOnPage(timeOnPage)

  const createHandler = async () => {
    setSubmitClicked(true)
    if (isCreating || fetchingOwnerDetails) return

    submitClickedCount.current++

    if (isValidRepoName && descriptionIsValid && ownerSelection && !hasInvalidPropertyValues) {
      updateTimeSpentOnPage(true)

      const body: RepoCreateBodyWithV2Metrics = {
        owner: ownerSelection.name,
        ['template_repository_id']: selectedTemplateRepo?.id.toString() || '',
        ['include_all_branches']: includeAllBranches ? '1' : '0',
        repository: {
          name: repositoryName,
          visibility: selectedVisibility,
          description,
          ['auto_init']: addReadme ? '1' : '0',
          ['license_template']: selectedLicense.id,
          ['gitignore_template']: selectedGitignoreTemplate.id,
        },
        metrics: {
          ['user_filtered_dropdown']: userFilteredDropdown,
          ['user_set_template']: userSetTemplate,
          ['user_changed_default_owner']: userChangedDefaultOwner,
          ['user_changed_owner_after_setting_template']: userChangedOwnerAfterSettingTemplate,
          ['created_from_organization']: pathname.startsWith('/organizations'),
          ['prepopulated_template']: !!prepopulatedTemplate,
          ['owner_has_marketplace_apps']: !!ownerHasMarketplaceApps,
          ['user_interacted_with_marketplace_apps']: userInteractedWithMarketplaceApps,
          ['user_is_admin']: ownerSelection.adminableByCurrentUser,
          ['elapsed_ms']: timeOnPage.current,
          ['submit_clicked_count']: submitClickedCount.current,
          ['submit_errors']: submitErrors,
          ['clicked_suggested_repo_name']: clickedSuggestedRepoName,
          ['used_suggested_repo_name']: repositoryName === suggestedRepoName,
          ['submitted_using_v2']: true,
        },
      }

      if (manuallyInstalledSelectedMarketplaceApps.length) {
        const apps = manuallyInstalledSelectedMarketplaceApps.reduce<Record<string, 'on'>>((acc, app) => {
          acc[app] = 'on'
          return acc
        }, {})
        body['quick_install'] = {[ownerSelection.name]: apps}
      }

      const canEditPropertyValues = ownerSelection.editableDefinitionNames.length > 0
      if (canEditPropertyValues) {
        const changedProperties = propertyFieldsToChangedPropertiesMap(
          ownerSelection.requiredDefinitions,
          propertyValuesMap,
        )
        if (Object.keys(changedProperties).length) {
          body['custom_properties'] = changedProperties
        }
      }

      setIsCreating(true)
      try {
        const result = await verifiedFetchJSON(repositoriesPath(), {
          method: 'POST',
          body,
        })

        if (result.redirected) {
          navigate(result.url)
        } else {
          const {data} = await result.json()
          if (result.ok) {
            navigate(data.redirect)
          } else {
            setCreateError(data.error)
            setIsCreating(false)
            setSubmitErrors(arr => [...arr, 'server_validation'])
          }
        }
      } catch {
        setCreateError('Something went wrong!')
        setIsCreating(false)
        setSubmitErrors(arr => [...arr, 'server_error'])
      }
    } else {
      const errors: string[] = []
      if (!isValidRepoName) {
        errors.push(`repo_name_${repoNameValidityReason}`)
      }

      if (!ownerSelection) {
        errors.push('missing_owner_selection')
      }

      if (!descriptionIsValid) {
        errors.push('description_too_long')
      }

      if (hasInvalidPropertyValues) {
        errors.push('invalid_properties')
      }

      setSubmitErrors(arr => [...arr, ...errors])

      if (!ownerSelection) {
        ownerRepoSelectionRef.current?.focusOwnerDropdown()
        return
      } else if (!isValidRepoName) {
        ownerRepoSelectionRef.current?.focusRepoInput()
        return
      } else if (!descriptionIsValid) {
        descriptionRef.current?.focus()
        return
      }
    }
  }

  const ownerHasMarketplaceApps = ownerSelection && ownerSelection.installableApps.length > 0
  const hasRequiredProperties = ownerSelection?.requiredDefinitions && ownerSelection.requiredDefinitions.length > 0
  const expandConfigurationSection = !hasRequiredProperties || propertiesValidationPassed

  return (
    <RepoCreationForm
      flash={createError || errorMessage}
      title="Create a new repository"
      description={
        <div>
          Repositories contain a project&apos;s files and version history.
          {repositoryImportLinkDataAttributes && (
            <ImportPrompt usePromptV2 repositoryImportLinkDataAttributes={repositoryImportLinkDataAttributes} />
          )}
        </div>
      }
      protectedOrgLogins={protectedOrgLogins}
      onSubmit={createHandler}
      submitButton={
        expandConfigurationSection && (
          <Button type="submit" variant="primary" disabled={isCreating} className="mt-4">
            {isCreating ? 'Creating repository…' : 'Create repository'}
          </Button>
        )
      }
      isStaffUser={isStaffUser}
      staffFeedbackUrl={staffFeedbackUrl}
      useHeaderV2
    >
      {isTemplatePrepopulated && hasTemplateRepos && <div className="mt-4">{templateDropdown}</div>}
      <Timeline clipSidebar className={styles.timelineWrapper}>
        <Timeline.Item {...testIdProps('general-item')} className={styles.timelineItem}>
          <Timeline.Badge>1</Timeline.Badge>
          <Timeline.Body>
            <h2 className={styles.timelineItemHeading}>General</h2>
            <div className={styles.timelineItemBody}>
              <OwnerRepoSelection
                ref={ownerRepoSelectionRef}
                repositoryName={repositoryName}
                onRepoChange={newRepoName => {
                  setRepoNameChanged(true)
                  setRepositoryName(newRepoName)
                }}
                ownerItems={ownerItems}
                selectedOwner={ownerSelection}
                onOwnerChange={(owner: OwnerItem) => {
                  onOwnerChange(owner)
                  setPropertiesValidationPassed(false)
                  setPropertiesValidationClicked(false)
                }}
                onFilterChange={() => setUserFilteredDropdown(true)}
                onValidityChange={({valid, invalidReason}) => {
                  setIsValidRepoName(valid)
                  setRepoNameValidityReason(invalidReason)
                }}
                hideRepoBlankCheck={!submitClicked && !repoNameChanged}
                hideSelectOwnerCheck={!submitClicked}
                useV2OwnerSelection
              />
              <RepoNameGeneratorV2
                suggestedRepoName={suggestedRepoName}
                onClick={(suggestedName: string) => {
                  setClickedSuggestedRepoName(true)
                  setRepositoryName(suggestedName)
                }}
              />
              <DescriptionV2
                ref={descriptionRef}
                description={description}
                onDescriptionChange={setDescription}
                isValid={descriptionIsValid}
                setIsValid={setDescriptionIsValid}
              />
            </div>
          </Timeline.Body>
        </Timeline.Item>
        {hasRequiredProperties && (
          <Timeline.Item {...testIdProps('properties-item')} className={styles.timelineItem}>
            <Timeline.Badge>2</Timeline.Badge>
            <Timeline.Body>
              <Stack direction="horizontal" justify="space-between">
                <Stack.Item>
                  <h2 className={styles.timelineItemHeading}>Required properties</h2>
                  {!showReadOnlyPropertiesSummary && (
                    <span className="fg-muted">This organization requires the following custom properties</span>
                  )}
                </Stack.Item>
                {showReadOnlyPropertiesSummary && (
                  <Stack.Item>
                    <Button variant="invisible" onClick={() => setShowReadOnlyPropertiesSummary(false)}>
                      Edit
                    </Button>
                  </Stack.Item>
                )}
              </Stack>
              <div className={styles.timelineItemBody}>
                {propertiesValidationClicked && hasInvalidPropertyValues && (
                  <Banner title="The following property inputs have errors:" variant="critical">
                    <span>
                      {ownerSelection.requiredDefinitions
                        .filter(definition => invalidPropertyValues.has(definition.propertyName))
                        .map((erroredProperty, index) => {
                          const {propertyName} = erroredProperty
                          return (
                            <React.Fragment key={propertyName}>
                              <Link
                                href="#"
                                inline
                                muted
                                onClick={event => {
                                  event.preventDefault()
                                  propertiesTableRef.current?.focusInput(propertyName)
                                }}
                              >
                                {propertyName}
                              </Link>
                              {index < invalidPropertyValues.size - 1 && ', '}
                            </React.Fragment>
                          )
                        })}
                    </span>
                  </Banner>
                )}
                <CustomPropertyValuesTableV2
                  ref={propertiesTableRef}
                  definitions={ownerSelection.requiredDefinitions}
                  editableDefinitions={editableDefinitions}
                  propertyValuesMap={propertyValuesMap}
                  setPropertyValue={setPropertyValue}
                  revertPropertyValue={revertPropertyValue}
                  showLockMessages={false}
                  showUndo={false}
                  orgName={ownerSelection.name}
                  showSummary={showReadOnlyPropertiesSummary}
                />
              </div>
              {!showReadOnlyPropertiesSummary && (
                <Stack direction="horizontal" justify="end" className="mt-4">
                  <Button
                    variant="primary"
                    onClick={() => {
                      setPropertiesValidationClicked(true)
                      if (!hasInvalidPropertyValues) {
                        setPropertiesValidationPassed(true)
                        setShowReadOnlyPropertiesSummary(true)
                      }
                    }}
                  >
                    Continue: Configuration
                  </Button>
                </Stack>
              )}
            </Timeline.Body>
          </Timeline.Item>
        )}
        <Timeline.Item {...testIdProps('configuration-item')} className={styles.timelineItem}>
          <Timeline.Badge>{hasRequiredProperties ? 3 : 2}</Timeline.Badge>
          <Timeline.Body>
            <h2 className={styles.timelineItemHeading}>Configuration</h2>
            {expandConfigurationSection && (
              <div className={styles.timelineItemBody}>
                <VisibilitySelectionV2
                  ownerSelection={ownerSelection}
                  privateModeEnabled={privateModeEnabled}
                  displayedVisibilities={displayedVisibilities}
                  selectedVisibility={selectedVisibility}
                  onVisibilityChange={setUserSelectedVisibility}
                  tradeControlsPrivateRepoCreationWarning={tradeControlsPrivateRepoCreationWarning}
                  tradeControlsUserPrivateRepoCreationWarning={tradeControlsUserPrivateRepoCreationWarning}
                />
                {!isTemplatePrepopulated && hasTemplateRepos && templateDropdown}
                {!selectedTemplateRepo && (
                  <InitializeRepositoryOptionsV2
                    docsUrls={docsUrls}
                    addReadme={addReadme}
                    onAddReadmeChange={setAddReadme}
                    selectedGitignoreTemplate={selectedGitignoreTemplate}
                    onSelectedGitignoreTemplateChange={setSelectedGitignoreTemplate}
                    licenses={licenses}
                    selectedLicense={selectedLicense}
                    onSelectedLicenseChange={setSelectedLicense}
                    isGitHubEnterprise={isGitHubEnterprise}
                  />
                )}
                {ownerHasMarketplaceApps && (
                  <MarketplaceAppsSelectionV2
                    manuallySelectedListingIds={manuallyInstalledSelectedMarketplaceApps}
                    onListingsSave={selectedListings => {
                      setUserInteractedWithMarketplaceApps(true)
                      setManuallyInstalledSelectedMarketplaceApps(selectedListings)
                    }}
                    ownerSelection={ownerSelection}
                  />
                )}
              </div>
            )}
          </Timeline.Body>
        </Timeline.Item>
      </Timeline>
    </RepoCreationForm>
  )
}

try{ CreateFormV2.displayName ||= 'CreateFormV2' } catch {}